      "summary": "“迪迦”一词意为印度尼西亚语中神圣的数字\"3\"。\n约在三千万年前，人类处于超古代文明时期，守护人类的巨人们发生内战，原是地球最强的黑暗战士迪迦在受幽怜的感动后选择成为光之战士，使自己的黑暗力量长眠。奇杰拉花朵盛开，人们全部都陷入了因奇杰拉的花粉而产生的幻觉，认为已不再需要巨人。光之巨人不能干涉人类的选择，于是巨人把自己战斗的躯体隐藏在金字塔后，化作光离开了地球，回到了自己的故乡。邪神加坦杰厄带着毁灭的黑暗降临，超古代文明毁灭。\n21世纪初期，地球不再有侵略和战争，人类期盼已久的和平终于到来了。地球防卫军也因此完成了历史使命，TPC（地球和平联合组织）成立，人类迎来了新的时代。但是，如超古代警卫团团长幽怜所预言：\"哥尔赞\"及\"美尔巴\"出现了。在怪兽攻击的目标——金字塔内，发现了3座巨大的石像。2座巨石像被怪兽摧毁。在这紧要关头，因为继承了超古代战士的基因，因此可以和金字塔的迪迦石像结合在一起的大古队员全身被光所包围，并融身于剩下的石像内——迪迦·奥特曼苏醒了。",
