      "summary": "“不死”是一个不死不灭的生命。\n\n而他的敌人，是一个袭击人类，想要毁灭人类的势力“叩门者”。\n虽然在一场大战后，不死取得了胜利，但他还需要继续守护全人类。\n于是他将自己的身体扩张开来，如同树木一般将抵抗之根深植于大地。\n\n数百年后，世界来到现代。\n这是一个前所未有得和平世界。\n\n不死有了新的朋友和新的家\n他觉得，在这个能满足一切的世界中，可以享受自己的幸福。\n然而危险的阴影再次向他逼近。\n那阴影便是会对人的内心乘虚而入的宿敌。\n制造自己的观察者，其真正的目的是什么？\n不死面临新的考验，他必须做出重要的选择。\n\n不死之身的“不死”的故事，《现代篇》就此揭开序幕。\n",
