      "summary": "新学期开始，青春学院实力强劲的网球部的来了一个初一新生——越前龙马。虽然帮助网球部其他新生出头不被高年级欺负，不过他的态度真是跩的可以，于是很快就和前辈用比赛决胜负。出人意料的是他的实力也确实高的惊人，引起了网球部指导老师和社长手冢的注意，并破例将他选入正式队员队伍，开始了通往全国大赛的征途……\n\n其实龙马的父亲越前南次郎也曾是在世界网坛昙花一现的职网球员，在美国打败所有职业网球高手赢得冠军，却因不明原因退出网坛，归隐在日本一家寺院。龙马从小在父亲近乎捉弄的态度下学习网球，对他来说网球并不是爱好，而是打败父亲的目标，因此在他心中有一个难以超越的背影。\n\n在和队友、对手的比赛交流中，龙马渐渐看清了一个更有意义的目标——全国大赛，摆脱要超越父亲的压力，在追求梦想的冠军的过程中展开属于自己的网球生涯。",
